import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.gravity_ff import ArmGravityFeedforward  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BEAKER_CFG, TASK_CFG  # noqa: E402
from src.weight_estimate import hand_load  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402

STILL_SPEED = 0.005          # rad/s: every joint of the arm slower than this (the module's own settled speed is 0.02)
WINDOW_S = 0.30              # s: the mean is taken over this long a still window
LOOSE_SPEED = 0.02           # rad/s: for the extra reading at the end of BACK (the module's settled speed)
LOOSE_WINDOW_S = 0.20
TIMEOUT_S = 6.0
H = {"events": [], "arm": None, "S": None, "slip": {"rel0": None, "max_mm": 0.0, "track": True, "at": {}}}


def make_hook():
    def hook(modules, model, data):
        m = modules["manipulation"]
        S, arm = m["state"], m["arm"]
        H["arm"], H["S"] = arm, S
        step0 = m["step"]

        def step(obs):
            i0 = S["i"]
            st = S["steps"][i0] if S["steps"] and i0 < len(S["steps"]) else None
            t0 = S["t0"]
            out = step0(obs)
            if st is not None and S["i"] > i0:
                T = st.get("T")
                H["events"].append({"prim": S["ctx"].get("primitive"), "name": st["name"], "kind": st["kind"], "t": float(obs["time"]), "last": S["i"] >= len(S["steps"]),
                                    "motion_end": None if (T is None or t0 is None) else float(t0 + T)})
            return out
        m["step"] = step
        return modules
    return hook


def make_sampler(model, data):
    arm_name = TASK_CFG["arm"]
    aid = [mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{arm_name}_joint{i}_ctrl") for i in range(1, 8)]
    gff = ArmGravityFeedforward.from_model(model)
    bb = model.body("task_beaker").id
    R = {"t": [], "qd": [], "q": [], "tau": [], "done_events": 0, "pending": [], "results": []}

    def measure(label, ev, speed_thr, window_s, strict):
        """If the last `window_s` of ticks are all still, take the reading; True when taken."""
        n = int(round(window_s * 150))
        if len(R["t"]) < n:
            return False
        qd = np.abs(np.array(R["qd"][-n:])).max(axis=1)
        if np.any(qd >= speed_thr):
            return False
        q = np.mean(R["q"][-n:], axis=0)
        tau = np.mean(R["tau"][-n:], axis=0)
        res = hand_load(model, q, tau, H["arm"], gff)
        # how long it took to be still: from the end of the minimum-jerk motion to the start of the still stretch (all ticks since below the threshold)
        allqd = np.abs(np.array(R["qd"])).max(axis=1)
        k = len(allqd)
        while k > 0 and allqd[k - 1] < speed_thr:
            k -= 1
        onset = R["t"][k] if k < len(R["t"]) else R["t"][-1]
        me = ev.get("motion_end")
        R["results"].append({"label": label, "strict": strict, "event": ev["name"], "trigger_t": ev["t"], "reading_t": R["t"][-1], "window_s": window_s, "speed_threshold": speed_thr,
                             "max_speed_in_window": float(qd.max()), "still_since_t": float(onset), "seconds_motion_end_to_still": None if me is None else max(0.0, float(onset - me)),
                             "seconds_trigger_to_reading": float(R["t"][-1] - ev["t"]), "weight_n": res["weight_n"], "mass_kg": res["mass_kg"], "unexplained_down": res["unexplained_down"],
                             "free_mag_n": res["free_mag_n"], "free_force_n": [float(x) for x in res["free_force_n"]], "angle_from_down_deg": res["angle_from_down_deg"],
                             "unexplained_free": res["unexplained_free"], "extra_nm": [float(x) for x in res["extra_nm"]]})
        return True

    def step(obs):
        t = float(data.time)
        arm = H["arm"]
        if arm is None:
            return None
        R["t"].append(t)
        R["qd"].append(data.qvel[arm.vadr].copy())
        R["q"].append(data.qpos.copy())
        R["tau"].append(data.actuator_force[aid].copy())
        S = H["S"]
        # slip: the beaker in the pad frame, from the start of the lift until the place's BACK starts
        steps = S.get("steps") or []
        cur = steps[S["i"]] if S.get("i") is not None and S["i"] < len(steps) else None
        prim = S["ctx"].get("primitive")
        sl = H["slip"]
        if cur is not None and sl["track"]:
            p, Rm = arm.pad_pose(data)
            rel = Rm.T @ (data.xpos[bb] - p)
            if prim == "pick" and cur["name"] == "UP" and sl["rel0"] is None:
                sl["rel0"] = rel.copy()
            if sl["rel0"] is not None:
                d = 1000 * float(np.linalg.norm(rel - sl["rel0"]))
                sl["max_mm"] = max(sl["max_mm"], d)
                sl["last_mm"] = d
            if prim == "place" and cur["name"] == "BACK":
                sl["track"] = False
        # new step-end events
        while R["done_events"] < len(H["events"]):
            ev = H["events"][R["done_events"]]
            R["done_events"] += 1
            if ev["last"] and ev["prim"] in ("pick", "place"):
                R["pending"].append((f"{ev['prim']} handoff (end of the {ev['prim']}, arm still)", ev, STILL_SPEED, WINDOW_S, True))
            elif ev["prim"] == "place" and ev["name"] == "BACK":
                R["pending"].append(("place, end of BACK (extra, module's settled speed)", ev, LOOSE_SPEED, LOOSE_WINDOW_S, False))
        keep = []
        for item in R["pending"]:
            label, ev, thr, win, strict = item
            if measure(label, ev, thr, win, strict):
                continue
            if t - ev["t"] > TIMEOUT_S:
                R["results"].append({"label": label, "strict": strict, "event": ev["name"], "trigger_t": ev["t"], "failed": f"not still for {win} s below {thr} rad/s within {TIMEOUT_S} s"})
                continue
            keep.append(item)
        R["pending"] = keep
        return None
    return {"name": "handoff_sampler", "step": step, "state": R}


def main(args):
    cfg = {**BEAKER_CFG, "liquid_mass": args.liquid}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    task = make_pipeline_task(PLAN4, module_hook=make_hook())
    gc.collect()
    sim = load_task(TASK_CFG, cameras=True, beaker_cfg=cfg)
    holder = {}

    def extra(m, d):
        holder["s"] = make_sampler(m, d)
        return {"handoff_sampler": holder["s"]}
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", extra_sources=extra, stop_after_handoff_s=None)
    state = task["pipeline"]["orchestrator"]["state"]
    ok, _ = task["check_success"](sim.model, sim.data)
    true_kg = float(sim.model.body_mass[sim.model.body("task_beaker").id])          # the answer key, read only now
    res = {"liquid_kg": args.liquid, "true_total_kg": true_kg, "outcome": s["outcome"], "failure": state["failure"], "status": state["status"], "beaker_on_hotplate": bool(ok),
           "readings": holder["s"]["state"]["results"], "slip": {"max_mm": H["slip"]["max_mm"], "last_mm": H["slip"].get("last_mm"), "rel0_m": None if H["slip"]["rel0"] is None else [float(x) for x in H["slip"]["rel0"]]},
           "thresholds": {"still_speed": STILL_SPEED, "window_s": WINDOW_S, "loose_speed": LOOSE_SPEED, "loose_window_s": LOOSE_WINDOW_S}}
    tmp = out / "result.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "result.json")
    print(f"true total {1000 * true_kg:.0f} g; outcome {s['outcome']}; slip max {H['slip']['max_mm']:.2f} mm", flush=True)
    for r in res["readings"]:
        if "failed" in r:
            print("  ", r["label"], "FAILED:", r["failed"], flush=True)
        else:
            print(f"   {r['label']}: {1000 * r['mass_kg']:.1f} g, still after {r['seconds_motion_end_to_still']}, fit angle {r['angle_from_down_deg']:.1f} deg, unexplained {100 * r['unexplained_down']:.0f} % (down) {100 * r['unexplained_free']:.0f} % (free)", flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--liquid", type=float, required=True)
    ap.add_argument("--out", required=True)
    main(ap.parse_args())
